import{_ as p,I as t,o as f,c as y,j as n,a as i,J as o,b6 as a}from"./chunks/framework.COUcLbTA.js";const x=JSON.parse(`{"title":"A Brief History of AI: From Symbolic Logic to Hundred-Billion-Parameter Large Models","description":"Over 70 years, AI has experienced three waves and two winters, ultimately converging into today's era of large models.","frontmatter":{"title":"A Brief History of AI: From Symbolic Logic to Hundred-Billion-Parameter Large Models","description":"Over 70 years, AI has experienced three waves and two winters, ultimately converging into today's era of large models."},"headers":[],"relativePath":"en/appendix/8-artificial-intelligence/ai-history.md","filePath":"en/appendix/8-artificial-intelligence/ai-history.md"}`),b={name:"en/appendix/8-artificial-intelligence/ai-history.md"};function w(v,e,k,T,I,A){const r=t("AiEvolutionDemo"),s=t("DiscriminativeVsGenerativeDemo"),l=t("FoundationDemo"),d=t("PerceptronDemo"),h=t("BackpropagationDemo"),c=t("NeuralNetworkVisualizationDemo"),m=t("AttentionMechanismDemo"),u=t("GPTEvolutionDemo"),g=t("AIErasComparisonDemo");return f(),y("div",null,[e[0]||(e[0]=n("h1",{id:"a-brief-history-of-ai-from-symbolic-logic-to-hundred-billion-parameter-large-models",tabindex:"-1"},[i("A Brief History of AI: From Symbolic Logic to Hundred-Billion-Parameter Large Models "),n("a",{class:"header-anchor",href:"#a-brief-history-of-ai-from-symbolic-logic-to-hundred-billion-parameter-large-models","aria-label":"Permalink to “A Brief History of AI: From Symbolic Logic to Hundred-Billion-Parameter Large Models”"},"​")],-1)),e[1]||(e[1]=n("p",null,[i("Over 70 years, AI has experienced "),n("strong",null,"three waves and two winters"),i(` — from the logical deduction of symbolism, to the neural networks of connectionism, to the reinforcement learning of behaviorism — ultimately converging into today's era of large models. Understanding AI's history helps us see the true source of the "intelligence" behind modern large models.`)],-1)),o(r),o(s),e[2]||(e[2]=n("hr",null,null,-1)),e[3]||(e[3]=n("h2",{id:"i-theoretical-foundations-the-birth-of-symbolism-1940s–1950s",tabindex:"-1"},[i("I. Theoretical Foundations & the Birth of Symbolism (1940s–1950s) "),n("a",{class:"header-anchor",href:"#i-theoretical-foundations-the-birth-of-symbolism-1940s–1950s","aria-label":"Permalink to “I. Theoretical Foundations & the Birth of Symbolism (1940s–1950s)”"},"​")],-1)),e[4]||(e[4]=n("p",null,'Before computers became widespread, pioneers were already asking: "Can machines think like humans?" Research in this period focused on mathematical modeling of brain neurons, exploration of computation theory, and automation of logical reasoning. The 1956 Dartmouth Conference officially declared "Artificial Intelligence" as an independent discipline.',-1)),o(l),e[5]||(e[5]=a('<h3 id="_1-1-core-theories-milestone-events" tabindex="-1">1.1 Core Theories &amp; Milestone Events <a class="header-anchor" href="#_1-1-core-theories-milestone-events" aria-label="Permalink to “1.1 Core Theories &amp; Milestone Events”">​</a></h3><ul><li><strong>The First Vision of Neural Networks (1943)</strong>: Neurophysiologist Warren McCulloch and mathematician Walter Pitts proposed the <strong>MP neuron model</strong>. They were the first to abstract the workings of human brain neurons into simple mathematical formulas, proving that &quot;neural networks are computable&quot; — the ancestor of every deep network today.</li><li><strong>Turing&#39;s Ultimate Question (1950)</strong>: Alan Turing, the father of computer science, published a history-changing paper <em>Computing Machinery and Intelligence</em>, proposing the famous <strong>Turing Test</strong>. He sidestepped the philosophical debate of &quot;what is intelligence&quot; and offered a pragmatic operational standard: if a machine can fool a human in conversation into thinking it&#39;s a person, it possesses intelligence.</li><li><strong>The Discipline Is Born (1956)</strong>: At the Dartmouth summer workshop, young scholars including John McCarthy and Marvin Minsky gathered together. McCarthy coined the term &quot;Artificial Intelligence&quot; in the proposal — and that year became known as Year Zero of AI.</li></ul><div class="tip custom-block"><p class="custom-block-title">Symbolism</p><p>In early AI research, <strong>symbolism</strong> held absolute dominance. Since computers of the time ran on logic circuits, scholars naturally assumed: <strong>the essence of intelligence is symbolic manipulation</strong>. If we encode the world&#39;s knowledge into symbols the computer can understand (concepts, rules) and process them with a logic inference engine (IF-THEN rules), the machine can think like a human. This was a <strong>top-down</strong> approach, heavily dependent on human expert knowledge input.</p></div><hr><h2 id="ii-the-golden-age-of-symbolism-the-first-ai-wave-1960s–1970s" tabindex="-1">II. The Golden Age of Symbolism &amp; the First AI Wave (1960s–1970s) <a class="header-anchor" href="#ii-the-golden-age-of-symbolism-the-first-ai-wave-1960s–1970s" aria-label="Permalink to “II. The Golden Age of Symbolism &amp; the First AI Wave (1960s–1970s)”">​</a></h2><p>In the first decade or so after its birth, AI enjoyed a period of blind optimism. Researchers believed that since machines could already prove mathematical theorems, writing programs to solve any human problem was just around the corner.</p><h3 id="_2-1-the-glory-days-of-expert-systems" tabindex="-1">2.1 The Glory Days of Expert Systems <a class="header-anchor" href="#_2-1-the-glory-days-of-expert-systems" aria-label="Permalink to “2.1 The Glory Days of Expert Systems”">​</a></h3><p>The crowning achievement of symbolism was the <strong>Expert System</strong>. By feeding top experts&#39; &quot;rules of thumb&quot; into a computer, the system could perform high-level diagnosis or decision-making in specific vertical domains.</p><table tabindex="0"><thead><tr><th>Expert System</th><th>Year</th><th>Historical Significance</th></tr></thead><tbody><tr><td><strong>Dendral</strong></td><td>1965</td><td><strong>The first expert system</strong> — it could infer chemical molecular structures from mass spectrometry data, matching human chemists in performance.</td></tr><tr><td><strong>MYCIN</strong></td><td>1977</td><td>Diagnosed blood infections and recommended antibiotics with 69% accuracy, outperforming many non-specialist doctors of the time.</td></tr><tr><td><strong>XCON</strong></td><td>1980</td><td>The most commercially successful early expert system, helping DEC auto-configure computer systems based on customer needs, saving the company $40 million per year.</td></tr></tbody></table><p>Yet behind the glory of expert systems lay an insurmountable chasm.</p><h3 id="_2-2-the-first-ai-winter-1974–1980" tabindex="-1">2.2 The First AI Winter (1974–1980) <a class="header-anchor" href="#_2-2-the-first-ai-winter-1974–1980" aria-label="Permalink to “2.2 The First AI Winter (1974–1980)”">​</a></h3><p>Over time, people discovered that &quot;translating human knowledge into rules&quot; was a dead end. Three fatal limitations of symbolism ultimately led to a complete withdrawal of research funding:</p><p><strong>Knowledge Acquisition Bottleneck</strong>: Some knowledge humans can&#39;t even articulate (e.g., how to recognize a cat) — known as &quot;Polanyi&#39;s Paradox.&quot; Expert systems could only hard-code explicitly expressible rules and couldn&#39;t learn automatically.</p><p><strong>Combinatorial Explosion &amp; Brittleness</strong>: Real-world situations are too numerous to enumerate; without common sense, the system collapses the moment it encounters anything outside its rule base.</p><p><strong>Insufficient Compute &amp; Funding Cuts</strong>: The hardware of the time simply couldn&#39;t support explosive logical inference, and DARPA slashed R&amp;D budgets.</p><hr><h2 id="iii-expert-systems-the-second-ai-wave-1980s" tabindex="-1">III. Expert Systems &amp; the Second AI Wave (1980s) <a class="header-anchor" href="#iii-expert-systems-the-second-ai-wave-1980s" aria-label="Permalink to “III. Expert Systems &amp; the Second AI Wave (1980s)”">​</a></h2><p>By the 1980s, with the spread of microcomputers and specialized LISP machines, expert systems once again attracted commercial attention. The Japanese government even launched the ambitious &quot;Fifth Generation Computer Project,&quot; attempting to build machines that could understand natural language — triggering a global panic-driven investment frenzy.</p><h3 id="_3-1-the-boom-and-bust-of-commercial-applications" tabindex="-1">3.1 The Boom and Bust of Commercial Applications <a class="header-anchor" href="#_3-1-the-boom-and-bust-of-commercial-applications" aria-label="Permalink to “3.1 The Boom and Bust of Commercial Applications”">​</a></h3><p>In this era, nearly every major multinational was developing its own <strong>expert system</strong> (a program that translates human expert experience into thousands of IF-THEN rules). However, maintaining these systems became excruciating. Once rule bases exceeded tens of thousands of entries, adding one new rule often caused conflicts with ten existing ones. As general-purpose PCs exploded in performance in the late 1980s, expensive and closed proprietary AI machines became utterly uncompetitive.</p><div class="warning custom-block"><p class="custom-block-title">The Second AI Winter (1987–1993)</p><p>In 1987, the AI hardware market collapsed entirely. The &quot;Fifth Generation Computer Project&quot; was abandoned for being too detached from practical hardware architecture. Companies&#39; investments in expert systems went up in smoke, and AI research plunged into another trough — &quot;artificial intelligence&quot; even became a pejorative term in academia, synonymous with grant fraud.</p></div><h3 id="_3-2-connectionism-hibernating-in-the-dark" tabindex="-1">3.2 Connectionism Hibernating in the Dark <a class="header-anchor" href="#_3-2-connectionism-hibernating-in-the-dark" aria-label="Permalink to “3.2 Connectionism Hibernating in the Dark”">​</a></h3><p>Through these two boom-bust cycles, a completely different school of thought had been quietly developing — <strong>Connectionism</strong>, what we now call <strong>neural networks</strong>.</p>',23)),o(d),e[6]||(e[6]=a('<p>Connectionism was proposed as early as 1958 by Frank Rosenblatt in the form of the <strong>Perceptron</strong>. It mimics the brain by adjusting connection weights between neurons to learn. Rather than teaching the machine explicit &quot;rules,&quot; you show it massive &quot;examples&quot; and let it generalize on its own. However, in 1969, Minsky&#39;s book <em>Perceptrons</em> mathematically proved the limitations of single-layer networks (inability to solve even the simple XOR problem). This kept connectionism on the bench throughout symbolism&#39;s golden age — until the wheel of history turned to the 1990s.</p><hr><h2 id="iv-the-rise-of-machine-learning-the-revival-of-connectionism-1990s–2000s" tabindex="-1">IV. The Rise of Machine Learning &amp; the Revival of Connectionism (1990s–2000s) <a class="header-anchor" href="#iv-the-rise-of-machine-learning-the-revival-of-connectionism-1990s–2000s" aria-label="Permalink to “IV. The Rise of Machine Learning &amp; the Revival of Connectionism (1990s–2000s)”">​</a></h2><p>Entering the 1990s, AI underwent an important pragmatic shift. Instead of debating how to achieve &quot;magical human-like intelligence,&quot; the focus moved to using <strong>rigorous statistical methods</strong> to solve real-world classification and prediction problems. This was the rise of traditional <strong>Machine Learning (ML)</strong>.</p><h3 id="_4-1-from-rigid-rules-to-finding-mathematical-boundaries" tabindex="-1">4.1 From Rigid Rules to &quot;Finding Mathematical Boundaries&quot; <a class="header-anchor" href="#_4-1-from-rigid-rules-to-finding-mathematical-boundaries" aria-label="Permalink to “4.1 From Rigid Rules to &quot;Finding Mathematical Boundaries&quot;”">​</a></h3><p>In 1997, IBM&#39;s &quot;Deep Blue&quot; defeated world chess champion Garry Kasparov, winning a spectacular victory for symbolism. But academia immediately recognized this was merely a triumph of &quot;brute-force compute + massive hard-coded rules&quot; — Deep Blue didn&#39;t truly understand chess.</p><p>Meanwhile, classical ML algorithms like <strong>Support Vector Machines (SVM)</strong>, decision trees, and random forests rose to prominence, dominating the field for over a decade.</p><p>If the old expert systems told the computer: &quot;If the email contains &#39;you won,&#39; then it&#39;s spam,&quot; then <strong>machine learning&#39;s approach was: humans first define key features (feature engineering)</strong> — such as &quot;email length,&quot; &quot;special word frequency,&quot; &quot;sender credibility&quot; — then feed tens of thousands of labeled emails to the computer. In this multi-dimensional space, the <strong>SVM</strong> acts like a mathematician with a ruler, using kernel functions to draw the &quot;widest, safest mathematical boundary&quot; between normal and spam emails.</p><p>Despite SVM&#39;s success on many tasks, it had a fatal weakness: <strong>Feature Engineering was entirely dependent on humans.</strong> To recognize a cat in an image, human scientists had to teach the machine to &quot;first extract edges,&quot; then &quot;look for triangular ears.&quot; The machine couldn&#39;t find the cat on its own! This meant model capability was firmly capped by human cognition.</p><h3 id="_4-2-backpropagation-brings-neural-networks-back-to-life" tabindex="-1">4.2 Backpropagation Brings Neural Networks Back to Life <a class="header-anchor" href="#_4-2-backpropagation-brings-neural-networks-back-to-life" aria-label="Permalink to “4.2 Backpropagation Brings Neural Networks Back to Life”">​</a></h3><p>The true foundation of deep learning was laid during this period:</p>',11)),o(h),e[7]||(e[7]=a('<p>During this hibernation, Geoffrey Hinton and others further clarified the core value of <strong>Backpropagation</strong>: when a multi-layer neural network makes an incorrect prediction, the error can ripple backward layer by layer, telling each hidden neuron: &quot;Here&#39;s exactly how much responsibility you bear for this mistake — fix it next time!&quot;</p><p>This finally broke the 1960s shackles on neural networks, making networks with hidden layers viable. But with too little data and too weak hardware (not even decent GPUs), neural networks still couldn&#39;t fully defeat traditional ML models like SVM. That is, until <strong>three ignition points</strong> converged.</p><hr><h2 id="v-the-deep-learning-revolution-connectionism-takes-the-lead-2010s" tabindex="-1">V. The Deep Learning Revolution &amp; Connectionism Takes the Lead (2010s) <a class="header-anchor" href="#v-the-deep-learning-revolution-connectionism-takes-the-lead-2010s" aria-label="Permalink to “V. The Deep Learning Revolution &amp; Connectionism Takes the Lead (2010s)”">​</a></h2><p>In the 2010s, with the maturation of <strong>big data (e.g., the ImageNet project)</strong>, the <strong>explosion of compute (GPUs applied to massively parallel computation)</strong>, and <strong>algorithmic improvements (solving the vanishing gradient problem)</strong>, &quot;deep learning&quot; dramatically opened the curtain on the third AI wave.</p><p><strong>What fundamentally distinguishes deep learning from traditional ML? The hallmark is: automatic feature extraction (representation learning).</strong> Given enough layers (dozens to hundreds), a neural network can ingest raw pixels directly — its lower layers learn to recognize lines, middle layers learn to recognize fur textures, and upper layers directly identify &quot;cat.&quot; In this revolution, humans finally relinquished control and let the network discover the most important visual, audio, and textual features on its own.</p><h3 id="_5-1-comprehensive-breakthroughs-in-vision-competition" tabindex="-1">5.1 Comprehensive Breakthroughs in Vision &amp; Competition <a class="header-anchor" href="#_5-1-comprehensive-breakthroughs-in-vision-competition" aria-label="Permalink to “5.1 Comprehensive Breakthroughs in Vision &amp; Competition”">​</a></h3><p>In 2012, <strong>AlexNet</strong> (a classic Convolutional Neural Network, CNN), developed by Hinton&#39;s team, entered the famous ImageNet image classification competition. While others were still painstakingly extracting hand-crafted visual features, AlexNet delivered a devastating blow — slashing the error rate from 26% to 15.3%, shocking the entire traditional computer vision community. In the years that followed, virtually no paper that didn&#39;t use deep learning could be accepted at top conferences.</p><p>In the following years, AI technology advanced at breakneck speed:</p>',9)),o(c),e[8]||(e[8]=a('<table tabindex="0"><thead><tr><th>Year</th><th>Landmark Achievement</th><th>Lasting Impact</th></tr></thead><tbody><tr><td><strong>2014</strong></td><td><strong>GAN (Generative Adversarial Network)</strong> proposed</td><td>Two networks in an adversarial game (one forges, one detects), giving AI the ability to generate stunningly realistic images.</td></tr><tr><td><strong>2015</strong></td><td><strong>ResNet (Residual Network)</strong> introduced</td><td>Innovatively added &quot;shortcut&quot; connections, solving the problem of networks becoming untrainable as they grow deeper — enabling hundreds or thousands of layers.</td></tr><tr><td><strong>2016</strong></td><td><strong>AlphaGo</strong> defeats Lee Sedol</td><td>The pinnacle of deep learning combined with <strong>reinforcement learning</strong>, shattering the claim that &quot;machines can never beat humans at Go&quot; and making headlines worldwide.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Behaviorism &amp; Reinforcement Learning</p><p>AlphaGo represents a victory for another school — <strong>Behaviorism</strong>. It holds that intelligence arises from dynamic interaction between an agent and its environment, like training a dog to sit: reward correct behavior, punish mistakes. Through endless self-play in a vast virtual environment, AlphaGo discovered strategies that even top human players had never conceived.</p></div><h3 id="_5-2-transformer-the-cradle-of-large-models" tabindex="-1">5.2 Transformer: The Cradle of Large Models <a class="header-anchor" href="#_5-2-transformer-the-cradle-of-large-models" aria-label="Permalink to “5.2 Transformer: The Cradle of Large Models”">​</a></h3><p>In 2017, the gears of destiny began to turn. Google published the paper <em>Attention Is All You Need</em>, proposing an entirely new deep learning architecture — the <strong>Transformer</strong>.</p>',4)),o(m),e[9]||(e[9]=a('<p>Previously, when processing a sentence (e.g., with RNN models), AI could only read words one by one from left to right, easily forgetting earlier words by the time it reached the end. The Transformer&#39;s <strong>Self-Attention mechanism</strong> shattered this limitation: it lets the AI &quot;see the entire sentence at once&quot; and, upon encountering the word &quot;apple,&quot; automatically determine from context whether it refers to the fruit or Steve Jobs&#39; company.</p><p>It is inherently suited for parallel computation, can consume unlimited data, and can be stacked to enormous scale. At this moment, the foundation for Large Language Models (LLMs) was complete.</p><hr><h2 id="vi-the-large-model-era-the-dawn-of-general-intelligence-2018–present" tabindex="-1">VI. The Large Model Era &amp; the Dawn of General Intelligence (2018–Present) <a class="header-anchor" href="#vi-the-large-model-era-the-dawn-of-general-intelligence-2018–present" aria-label="Permalink to “VI. The Large Model Era &amp; the Dawn of General Intelligence (2018–Present)”">​</a></h2><p>When the Transformer met unlimited compute and massive data, the historical paradigm of AI development was forever changed. Scientists discovered an astonishing phenomenon: the attention-based architecture seemed insatiable. Previous deep learning models hit intelligence ceilings, but the Transformer could perfectly leverage GPUs&#39; massive parallelism — the more data and the deeper the network, the better it performed, seemingly without limit.</p><h3 id="_6-1-the-pre-train-fine-tune-paradigm-from-specialist-to-generalist" tabindex="-1">6.1 The &quot;Pre-train + Fine-tune&quot; Paradigm: From Specialist to Generalist <a class="header-anchor" href="#_6-1-the-pre-train-fine-tune-paradigm-from-specialist-to-generalist" aria-label="Permalink to “6.1 The &quot;Pre-train + Fine-tune&quot; Paradigm: From Specialist to Generalist”">​</a></h3><p>Originally, building AI meant &quot;one task, one small model&quot;: a dedicated translation model for translation, a dedicated chatbot model for chat — like training craftsmen who each know only one trade. But in 2018, with OpenAI&#39;s <strong>GPT-1</strong> and Google&#39;s <strong>BERT</strong>, a new paradigm emerged: <strong>&quot;scale is all you need.&quot;</strong></p><p>First comes <strong>Pre-training</strong>, which constitutes 99% of a large language model&#39;s core intelligence. Scientists poured trillions of words from the entire internet — articles, classic literature, computer code, encyclopedic knowledge — into a massive Transformer network. And the training task? Simply <strong>&quot;next-word prediction.&quot;</strong></p><p>To predict the next word in human language with extraordinary precision, the model is forced to internalize and compress the operating principles of the entire world within its hundreds of billions of neural parameters! It doesn&#39;t just master subject-verb-object grammar and learn that &quot;apple&quot; is a red fruit — it grasps the logic behind &quot;Newton discovered gravity because of a falling apple.&quot; Like a child who never deliberately studied a grammar textbook but, through reading millions of books, automatically gained the ability to understand the complex world.</p>',9)),o(u),e[10]||(e[10]=a('<p>From GPT-2 (1.5 billion parameters) to GPT-3 (175 billion parameters), scientists were stunned to discover <strong>Emergent Abilities</strong> — when a model grows large enough, quantitative change triggers terrifying qualitative change. Without any deliberate training, the massive model spontaneously &quot;figured out&quot; logical reasoning, code writing, and in-context learning. No human needed to explicitly teach it through code.</p><h3 id="_6-2-the-generative-ai-explosion-chatgpt-s-nuclear-moment" tabindex="-1">6.2 The Generative AI Explosion &amp; ChatGPT&#39;s Nuclear Moment <a class="header-anchor" href="#_6-2-the-generative-ai-explosion-chatgpt-s-nuclear-moment" aria-label="Permalink to “6.2 The Generative AI Explosion &amp; ChatGPT&#39;s Nuclear Moment”">​</a></h3><p>With a pre-trained model brimming with world knowledge, one final step remained to create the perfect personal AI assistant: <strong>Fine-tuning</strong>. The pre-trained model was only accustomed to blindly continuing text — it couldn&#39;t understand user &quot;instructions&quot; or conduct proper Q&amp;A interactions.</p><p>In November 2022, OpenAI ingeniously introduced <strong>RLHF (Reinforcement Learning from Human Feedback)</strong>. They hired large teams of experts to score and correct the model&#39;s responses. It was like taking a brilliant but unfiltered genius and establishing clear communication boundaries and etiquette guidelines, forcibly shaping it into a gentle, organized, and well-mannered conversational assistant. Thus, <strong>ChatGPT</strong> was born.</p><p>Overnight, AI was no longer a dry laboratory toy — it became a universal intelligent brain in every ordinary person&#39;s hands.</p><p>What followed was a magnificent multimodal era:</p><ul><li><strong>2023: Unlocking multiple senses.</strong> Image generation models like Midjourney and Stable Diffusion reshaped the digital art industry. <strong>GPT-4</strong>, released the same year, combined advanced visual understanding with long-range logical reasoning.</li><li><strong>2024 onward: Simulating the physical world.</strong> With the release of realistic video generation models like Sora, and real-time end-to-end voice models with full emotional nuance, AI expanded from pure text processing to comprehensive perception of the complete world — including 3D space, light and shadow, and subtle vocal emotions.</li></ul><hr><h2 id="vii-the-convergence-of-ai-s-three-schools-future-outlook" tabindex="-1">VII. The Convergence of AI&#39;s Three Schools &amp; Future Outlook <a class="header-anchor" href="#vii-the-convergence-of-ai-s-three-schools-future-outlook" aria-label="Permalink to “VII. The Convergence of AI&#39;s Three Schools &amp; Future Outlook”">​</a></h2><p>Looking back over these 70 years — from making machines prove mathematical theorems (symbolism), to finding statistical boundaries (classical ML), to winning at Go through trial and error (behaviorism/reinforcement learning), to large models that devour massive data and develop emergent common sense (the ultimate form of connectionism) — the development of artificial intelligence has never stopped.</p><p>Today&#39;s large models appear to have abandoned the manual coding of rigid &quot;rules&quot; (symbolism&#39;s original intent), but in reality, within the implicit parameters of their thousands of layers, they have learned and encapsulated &quot;dark rules&quot; far deeper than human logic. The <strong>Chain of Thought</strong> long-range reasoning in today&#39;s large pre-trained models — isn&#39;t that the rebirth of the symbolic school&#39;s pursuit of logical verification and rigorous step-by-step reasoning, now reincarnated within neural networks?</p><p><strong>Standing at the summit of the large model era and looking ahead, the path toward Artificial General Intelligence (AGI) is advancing along several profoundly broad avenues of exploration:</strong></p><ol><li><strong>Toward a Unified Neural Hub (Native Multimodality):</strong> Future models will no longer be Frankenstein-like assemblies of &quot;text model + voice model.&quot; Architectures like GPT-4o use a single super-network to simultaneously ingest, perceive, and understand text, images, video streams, and ultra-low-latency emotionally rich 3D audio waveforms.</li><li><strong>Embodied AI:</strong> When a supremely intelligent &quot;brain&quot; is imprisoned in a silicon data center, it cannot verify truth from the physical world. Through integration with Boston Dynamics-style humanoid robots, super AI may grow hands and, through physical trial and error, learn the same objective physical laws we live by.</li><li><strong>Agentic AI:</strong> Most LLMs today remain at the stage of &quot;passive text calculators answering one question at a time.&quot; In the AI Agent era, large models are granted <strong>the power to act independently</strong>. Give a single natural language instruction (e.g., &quot;Research and plan all flights, hotels for seeing the Northern Lights in Norway next week, and generate a calendar schedule&quot;), and the AI Agent will autonomously decompose it into dozens of sub-tasks, open virtual browsers, call real airline search APIs, perform complex verification and comparison. They are no longer passive echo chambers waiting for keystrokes — they are tireless digital workforces.</li></ol><p>In this spiraling technological journey, history is always strikingly similar but never repeats. We are witnessing the most exhilarating cross-section of history — the transition from &quot;force-feeding algorithms with rigid rules&quot; to &quot;letting machines autonomously define the laws of the world.&quot;</p>',14)),o(g)])}const _=p(b,[["render",w]]);export{x as __pageData,_ as default};
